ee:message.ee:set-payload:
%dw 2.0 output application/java
var incomingOrder = payload var rawItems = incomingOrder.items default [] var tolerance = p("order.amount.tolerance") as Number
// Accept numbers and numeric strings only fun isNumericValue(value) = value is Number or (value is String and (value matches /^-?[0-9]+(\.[0-9]+)?$/))
fun isValidItem(item) = item is Object and isNumericValue(item.quantity default null) and isNumericValue(item.unitPrice default null)
// ---------- STEP 1: validate BEFORE any "as Number" conversion ---------- var itemsAreValid = (rawItems is Array) and (sizeOf(rawItems) > 0) and (sizeOf(rawItems filter ((item) -> !isValidItem(item))) == 0)
var totalIsValid = isNumericValue(incomingOrder.totalAmount default null) var inputsValid = itemsAreValid and totalIsValid
// ---------- STEP 2: convert only if validation passed ---------- var orderItems = if (inputsValid) (rawItems map ((item) -> { productId: item.productId, productName: item.productName default "", quantity: item.quantity as Number, unitPrice: item.unitPrice as Number, lineTotal: (item.quantity as Number) * (item.unitPrice as Number) })) else []
var calculatedTotal = if (inputsValid) sum(orderItems map $.lineTotal) else 0 var submittedTotal = if (inputsValid) (incomingOrder.totalAmount as Number) else 0 var amountMatches = inputsValid and (abs(calculatedTotal - submittedTotal) <= tolerance)
var validationError = if (!(rawItems is Array) or sizeOf(rawItems) == 0) "Items are missing or empty" else if (!itemsAreValid) "Item quantity or unitPrice is not numeric" else if (!totalIsValid) "totalAmount is not numeric" else if (!amountMatches) "Submitted total does not match calculated total" else null
var shippingAddressValue = if (incomingOrder.shippingAddress is Object) write(incomingOrder.shippingAddress, "application/json") else (incomingOrder.shippingAddress default "") --- { orderId: incomingOrder.orderId, orderDate: incomingOrder.orderDate, customerId: incomingOrder.customer.customerId default incomingOrder.customerId, customerName: incomingOrder.customer.name default incomingOrder.customerName, customerEmail: incomingOrder.customer.email default incomingOrder.customerEmail, customerPhone: incomingOrder.customer.phone default incomingOrder.customerPhone default "", shippingAddress: shippingAddressValue, paymentMethod: incomingOrder.paymentMethod, currency: incomingOrder.currency, items: orderItems, originalItems: rawItems, submittedTotal: submittedTotal, calculatedTotal: calculatedTotal, amountMatches: amountMatches, validationError: validationError, correlationId: attributes.headers.correlationId default null }
